class Solution {
public:
    string getSmallestString(string s) {
        for (size_t i = 0; i + 1 < s.size(); ++i) {
            int d1 = s[i] - '0', d2 = s[i + 1] - '0';
            if (d1 % 2 == d2 % 2 && d1 > d2) {
                swap(s[i], s[i + 1]);
                break;
            }
        }
        return s;
    }
};

class Solution {
    public String getSmallestString(String s) {
        char[] chars = s.toCharArray();
        for (int i = 0; i + 1 < chars.length; ++i) {
            int d1 = chars[i] - '0', d2 = chars[i + 1] - '0';
            if (d1 % 2 == d2 % 2 && d1 > d2) {
                char tmp = chars[i];
                chars[i] = chars[i + 1];
                chars[i + 1] = tmp;
                break;
            }
        }
        return new String(chars);
    }
}

var getSmallestString = function(s) {
    const chars = s.split('');
    for (let i = 0; i + 1 < chars.length; ++i) {
        const d1 = Number(chars[i]), d2 = Number(chars[i + 1]);
        if (d1 % 2 === d2 % 2 && d1 > d2) {
            const tmp = chars[i];
            chars[i] = chars[i + 1];
            chars[i + 1] = tmp;
            break;
        }
    }
    return chars.join('');
};
